import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.LX5S0jbT.js";const c=JSON.parse('{"title":"Run Pi in tmux","description":"","frontmatter":{},"headers":[],"relativePath":"tmux.md","filePath":"tmux.md"}'),n={name:"tmux.md"};function o(r,e,d,h,u,l){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="run-pi-in-tmux" tabindex="-1">Run Pi in tmux <a class="header-anchor" href="#run-pi-in-tmux" aria-label="Permalink to &quot;Run Pi in tmux&quot;">​</a></h1><p>Pi works inside tmux, but tmux can report <code>Shift+Enter</code>, <code>Ctrl+Enter</code>, and plain <code>Enter</code> as the same key. Enable extended keys so Pi can distinguish them.</p><h2 id="check-your-tmux-version" tabindex="-1">Check your tmux version <a class="header-anchor" href="#check-your-tmux-version" aria-label="Permalink to &quot;Check your tmux version&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tmux</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -V</span></span></code></pre></div><p>For tmux 3.5 or newer, use the recommended CSI-u configuration below. For tmux 3.2 through 3.4, use the older-version configuration.</p><h2 id="enable-extended-keys-in-tmux-3-5-or-newer" tabindex="-1">Enable extended keys in tmux 3.5 or newer <a class="header-anchor" href="#enable-extended-keys-in-tmux-3-5-or-newer" aria-label="Permalink to &quot;Enable extended keys in tmux 3.5 or newer&quot;">​</a></h2><p>Add these lines to <code>~/.tmux.conf</code>:</p><div class="language-tmux vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tmux</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set -g extended-keys on</span></span>
<span class="line"><span>set -g extended-keys-format csi-u</span></span></code></pre></div><p>Pi requests extended-key reporting when the terminal does not provide the Kitty keyboard protocol directly. CSI-u is the most reliable format for forwarding modified keys through tmux.</p><h2 id="restart-tmux" tabindex="-1">Restart tmux <a class="header-anchor" href="#restart-tmux" aria-label="Permalink to &quot;Restart tmux&quot;">​</a></h2><p>The configuration applies to the tmux server. To guarantee that it is active, close your tmux sessions and start a new server.</p><p>If you choose to stop the server from the command line, save your work first. This command terminates every session managed by that server:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tmux</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kill-server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tmux</span></span></code></pre></div><h2 id="verify-modified-keys" tabindex="-1">Verify modified keys <a class="header-anchor" href="#verify-modified-keys" aria-label="Permalink to &quot;Verify modified keys&quot;">​</a></h2><p>Start Pi inside the new tmux session and check that:</p><ol><li><code>Shift+Enter</code> inserts a new line in the editor.</li><li><code>Enter</code> submits the prompt.</li><li><code>Alt+Enter</code> queues a follow-up on macOS and Linux. Windows and WSL use <code>Ctrl+Q</code> by default.</li></ol><p>If these keys still behave like plain <code>Enter</code>, verify that the terminal outside tmux can report modified keys. See <a href="./terminal-setup.html">Configure your terminal</a>.</p><h2 id="use-tmux-3-2-through-3-4" tabindex="-1">Use tmux 3.2 through 3.4 <a class="header-anchor" href="#use-tmux-3-2-through-3-4" aria-label="Permalink to &quot;Use tmux 3.2 through 3.4&quot;">​</a></h2><p>These versions support extended keys but not <code>extended-keys-format csi-u</code>. Add only:</p><div class="language-tmux vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tmux</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set -g extended-keys on</span></span></code></pre></div><p>Pi supports the xterm <code>modifyOtherKeys</code> format used by these versions. Restart tmux and repeat the verification steps.</p><p>For older versions, upgrade tmux or use Pi outside tmux rather than relying on modified Enter shortcuts.</p>`,22)])])}const m=t(n,[["render",o]]);export{c as __pageData,m as default};
